// ============================================================
// Live KPI Adapter
// Satisfies `KPIAdapter`. Connects to Firestore `kpi_snapshots`
// generated by functions/src/kpi.
// ============================================================
import { getKpiSnapshots } from "@/service/kpi";
import type {
  DateRangeKey,
  KPIAdapter,
  KPIValue,
  MetricSource,
  MetricStatus,
} from "@/lib/kpi/types";
import { METRIC_MAP } from "./registry";
import { mockAdapter } from "./mockAdapter";

export interface LiveMetricValue {
  value: number;
  computedAt: string;
  format?: string;
  sampleSize?: number;
  note?: string;
}

export interface LiveKPISnapshot {
  date: string;
  generatedAt: string;
  range: { start: string; end: string };
  metrics: Record<string, LiveMetricValue>;
  adapterStatus?: Record<
    string,
    { ok: boolean; message?: string; fetchedMetricCount: number }
  >;
}

/** How many trailing days each range covers. */
const RANGE_DAYS: Record<DateRangeKey, number> = {
  today: 1,
  week: 7,
  month: 30,
  quarter: 90,
  ytd: 90,
  custom: 45,
};

const ADAPTER_SOURCE_MAP: Record<string, MetricSource> = {
  hubspot: "HubSpot",
  firebase: "Firebase",
  "meta-ads": "Meta Ads",
  "google-ads": "Google Ads",
  stripe: "Stripe",
  quickbooks: "QuickBooks",
  plaid: "Plaid",
  asana: "CEG Brain",
  calendly: "CEG Brain",
  computed: "CEG Brain",
};

let snapshotsCache: LiveKPISnapshot[] = [];
let initialized = false;
const listeners = new Set<() => void>();

export function subscribeLiveAdapter(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

export function initSnapshotListener() {
  if (initialized || typeof window === "undefined") return;
  initialized = true;

  getKpiSnapshots()
    .then((docs) => {
      snapshotsCache = docs;
      listeners.forEach((cb) => cb());
    })
    .catch((err) => {
      console.warn("Failed to initialize Live KPI listener:", err);
    });
}

function statusFor(
  value: number,
  target: number | undefined,
  higherIsBetter: boolean,
): MetricStatus {
  if (target == null) return "neutral";
  const ratio = higherIsBetter ? value / target : target / value;
  if (ratio >= 0.98) return "ok";
  if (ratio >= 0.88) return "warn";
  return "danger";
}

export const liveAdapter: KPIAdapter = {
  name: "live",
  init: initSnapshotListener,

  getMetric(metricId: string, range: DateRangeKey): KPIValue | null {
    // Fall back to baseline mock adapter if snapshots are not yet loaded or Firestore is empty
    if (snapshotsCache.length === 0) {
      return mockAdapter.getMetric(metricId, range);
    }

    const def = METRIC_MAP[metricId];
    if (!def) return null;

    const days = Math.min(RANGE_DAYS[range] ?? 30, snapshotsCache.length);
    const window = snapshotsCache.slice(-days);

    const series = window.map((s) => ({
      date: s.date,
      value: s.metrics[metricId]?.value ?? 0,
    }));

    const latestVal = window[window.length - 1]?.metrics[metricId]?.value;
    const value =
      latestVal ?? mockAdapter.getMetric(metricId, range)?.value ?? 0;

    // Previous comparable window
    const prevWindow = snapshotsCache.slice(
      Math.max(0, snapshotsCache.length - days * 2),
      snapshotsCache.length - days,
    );
    const avg = (arr: { value: number }[]) =>
      arr.length ? arr.reduce((s, p) => s + p.value, 0) / arr.length : 0;

    const prevSeries = prevWindow.map((s) => ({
      value: s.metrics[metricId]?.value ?? 0,
    }));
    const previous = prevSeries.length ? avg(prevSeries) : avg(series);
    const currentAvg = avg(series);
    const deltaAbs = +(currentAvg - previous).toFixed(2);
    const delta =
      previous === 0
        ? 0
        : +(((currentAvg - previous) / previous) * 100).toFixed(1);

    const higherIsBetter = def.higherIsBetter !== false;
    const latestSnapshot = snapshotsCache[snapshotsCache.length - 1];

    return {
      ...def,
      higherIsBetter,
      value,
      previous: +previous.toFixed(2),
      delta,
      deltaAbs,
      status: statusFor(value, def.target, higherIsBetter),
      series,
      updatedAt: latestSnapshot?.generatedAt
        ? new Date(latestSnapshot.generatedAt).toLocaleTimeString("en-US", {
            hour: "numeric",
            minute: "2-digit",
          })
        : "live",
    };
  },

  getSyncStatus() {
    if (snapshotsCache.length === 0) {
      return mockAdapter.getSyncStatus();
    }

    const latest = snapshotsCache[snapshotsCache.length - 1];
    const adapterStatuses = latest.adapterStatus ?? {};

    const sources: MetricSource[] = [
      "HubSpot",
      "Firebase",
      "CEG Brain",
      "Stripe",
      "Meta Ads",
      "Google Ads",
      "QuickBooks",
      "Plaid",
      "Manual",
    ];

    return sources.map((source) => {
      const matchingKey = Object.keys(adapterStatuses).find(
        (key) => ADAPTER_SOURCE_MAP[key] === source,
      );
      const statusInfo = matchingKey ? adapterStatuses[matchingKey] : null;

      return {
        source,
        status: statusInfo ? (statusInfo.ok ? "live" : "error") : "live",
        lastSync: latest.generatedAt
          ? new Date(latest.generatedAt).toLocaleTimeString("en-US", {
              hour: "numeric",
              minute: "2-digit",
            })
          : "live",
      };
    });
  },
};
